const $=s=>document.querySelector(s);
const store={get(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}};
let saved=store.get('pp-saved',[]),progress=store.get('pp-progress',{}),category='all',savedOnly=false,book=null,page=0;
// Source rectangles in the original, unmodified transparent illustration sheet.
const spriteRegions={johnny:[47,0,204,316],pip:[321,25,225,288],rocket:[578,14,262,303],apple:[873,41,249,260],bag:[15,320,281,260],sock:[321,322,230,249],mars:[577,325,271,260],earth:[850,325,272,255],star:[10,591,270,256],telescope:[293,580,267,276],house:[560,588,286,271],tree:[850,575,272,287],openbook:[7,882,298,204],box:[309,865,266,234],fins:[575,890,270,209],window:[864,865,258,232],bear:[48,1086,211,314],boots:[297,1130,269,238],cloud:[568,1140,289,241],book:[864,1107,258,290]};
function pic(name,cls=''){const [x,y,w,h]=spriteRegions[name];return `<span class="picture ${cls}" data-picture="${name}" aria-hidden="true" style="aspect-ratio:${w}/${h};background-size:${1122/w*100}% ${1402/h*100}%;background-position:${x/(1122-w)*100}% ${y/(1402-h)*100}%"></span>`}
function art(kind='space',hero=false){return `<div class="painted-cover world-${kind==='space'?'space':'garden'}" aria-hidden="true">${kind==='space'?pic('mars','cover-planet')+pic('rocket','cover-rocket')+pic('johnny','cover-johnny')+pic('pip','cover-pip'):kind==='nature'?pic('tree','cover-tree')+pic('bear','cover-bear'):pic('house','cover-house')+pic('boots','cover-boots')}</div>`}
const books=[{id:'johnny',title:'Johnny Builds to Mars',kind:'space',age:[3,6],label:'AGES 4–8',time:'8 min',tag:'TODAY’S BIG ADVENTURE',summary:'One little builder. One very big idea. Join Johnny and his tiny robot as a cardboard rocket becomes an out-of-this-world adventure.',demo:true,pages:[['A very big idea','Johnny looked up at a little red dot in the sky. “Mars,” he whispered. “I wonder what it looks like up close.” In his garden, an empty box was waiting.','Tap the little red planet.','planet'],['A rocket from a box','Johnny found a box, two fins, and a shiny round window. “Every great adventure starts with a little making!” he said. Pip the robot brought the tape.','Tap all 3 pieces to build the rocket.','build'],['Snacks for space','“We must pack a snack!” said Johnny. He put three apples in his bag. Pip tried to pack a sock. “That is not a snack, Pip!” Johnny laughed.','Find and tap 3 apples.','apples'],['Ready, set, WHOOSH!','Johnny pulled on his helmet. Pip buckled up beside him. “Three… two… one!” The rocket wobbled, wiggled, and whooshed into their big make-believe sky.','Tap the countdown button 3 times.','launch'],['A sky full of sparkles','The stars looked like tiny lanterns. Johnny traced a path through the dark. Pip floated upside down. “Space is very good for silly dancing,” he beeped.','Light up all 5 stars.','stars'],['Hello, red planet','They landed with a gentle bump. Red rocks stretched as far as Johnny could see. Pip took one small step, then did a very big tumble. “I meant to do that!”','Tap Pip to see his silly space dance.','robot'],['A little piece of home','Johnny took out his last apple. He and Pip shared it on a red rock. Far away, Earth shone blue. “Mars is wonderful,” said Johnny, “but I miss home.”','Tap Earth to find the way home.','earth'],['The next big adventure','Johnny opened his eyes. He was back in his garden, sitting in his cardboard rocket. “Where next?” beeped Pip. Johnny smiled. “Let’s read a book and find out.”','Tap the book for a final surprise.','book']]},{id:'bear',title:'The Bear and the Two Travelers',kind:'nature',age:[3,6],label:'AGES 4–8',time:'3 min',tag:'A LITTLE FOREST WISDOM',summary:'Two travelers meet a bear in the woods—and learn what being a friend really means. A short retelling of Aesop’s public-domain fable.',pages:[['Into the woods','Two travelers walked into a quiet wood. The trees were tall, and the path was narrow. Suddenly, they heard a rustle. A bear was coming!','Find the 3 apples in the woods.','apples'],['Up a tree','One traveler quickly climbed a tree. His friend could not climb. So the friend lay very still on the ground and held his breath.','Tap the bear to see what happens.','bear'],['A quiet sniff','The bear sniffed the traveler’s face. The traveler stayed still. Then the bear turned and wandered away through the trees.','Light up 5 fireflies to guide the bear away.','stars'],['A true friend','The traveler in the tree climbed down. “What did the bear whisper?” he asked. “Never leave your friend when trouble comes,” said the other traveler.','Tap the book to collect your story star.','book']]},{id:'boots',title:'Puss in Boots',kind:'fairy',age:[6],label:'AGES 6–8',time:'4 min',tag:'ONCE UPON A TIME',summary:'A clever cat, a splendid pair of boots, and a plan to help a friend. A gentle, short retelling of the public-domain fairy tale.',pages:[['A surprising gift','A young miller had very little, except a cat. “Give me a pair of boots,” said the cat, “and I will help you.” The miller had never heard a cat talk before!','Tap the boots to get the cat ready.','boots'],['A gift for the king','The cat put on his boots and carried a gift to the king. “From my good friend, the Marquis of Carabas!” he announced. The miller wondered who that could be.','Collect 3 apples for the king.','apples'],['The cat’s clever plan','When the royal carriage came by, the cat introduced the miller as the Marquis. The miller bowed politely. The king invited him to ride along.','Find 5 sparkles along the royal road.','stars'],['A happy home','The cat helped his friend find a happy new life. The miller never forgot the clever friend who believed in him. And the cat? He always kept his wonderful boots.','Tap the book for your story star.','book']]}];
function render(){const q=$('#search').value.toLowerCase().trim(),age=$('#age').value;const list=books.filter(b=>(category==='all'||category===b.kind)&&(age==='all'||b.age.includes(+age))&&(!savedOnly||saved.includes(b.id))&&(b.title+' '+b.summary).toLowerCase().includes(q));$('#grid').innerHTML=list.map(b=>`<article class="book-card"><button class="cover" data-open="${b.id}" aria-label="Explore ${b.title}">${art(b.kind)}<span class="tag">${b.tag}</span><span class="cover-title">${b.id==='johnny'?'<small>Johnny builds</small>to Mars':b.id==='bear'?'<small>The bear and</small>the two travelers':'Puss in Boots'}</span></button><div class="book-meta"><h3>${b.title}</h3><button class="save-book" data-save="${b.id}" aria-label="${saved.includes(b.id)?'Unsave':'Save'} ${b.title}" aria-pressed="${saved.includes(b.id)}">${saved.includes(b.id)?'Saved':'Save'}</button></div><p class="subline">${b.label}<span>·</span>${b.time} read<span>·</span>Read and play</p><p class="subline">${b.demo?'Original demo story':'A classic, gently retold'}</p></article>`).join('');$('#empty').hidden=!!list.length;$('#resultCount').textContent=`${list.length} adventures to explore`;$('#savedCount').textContent=saved.length;document.querySelectorAll('[data-open]').forEach(el=>el.onclick=()=>details(el.dataset.open));document.querySelectorAll('[data-save]').forEach(el=>el.onclick=()=>{const id=el.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];store.set('pp-saved',saved);render()})}
function details(id){const b=books.find(x=>x.id===id);$('#detailBody').innerHTML=`<span class="eyebrow">${b.label} · ${b.pages.length} INTERACTIVE PAGES</span><h2>${b.title}</h2><p>${b.summary}</p><div class="dialog-actions"><button class="primary" id="start">Start reading</button>${progress[id]>0?'<button class="secondary" id="resume">Keep reading</button>':''}</div><p class="demo-note">${b.demo?'This is an original demonstration story, pending the text of the published book.':'A child-friendly retelling of a public-domain classic.'} Explore at your own pace, or turn the page whenever you like.</p>`;$('#start').onclick=()=>start(id,0);if($('#resume'))$('#resume').onclick=()=>start(id,progress[id]);$('#detail').showModal()}
function start(id,p=0){book=books.find(x=>x.id===id);page=Math.max(0,Math.min(p,book.pages.length-1));$('#detail').close();$('#library').hidden=true;$('#reader').hidden=false;drawPage();window.scrollTo(0,0)}
function stopSpeech(){if('speechSynthesis'in window)speechSynthesis.cancel()}
function home(){cleanupScene();$('#reader').hidden=true;$('#library').hidden=false;book=null;render();window.scrollTo(0,0)}
function finish(){cleanupScene();const completed=store.get('pp-complete',[]);if(!completed.includes(book.id))completed.push(book.id);store.set('pp-complete',completed);$('#reader').innerHTML=`<section class="finish">${pic('star','finish-star')}<span class="eyebrow">YOUR ADVENTURE HAS A HAPPY ENDING</span><h1>You read a whole story!</h1><p>You finished <strong>${book.title}</strong>.<br>Which part would you like to tell someone about?</p><div class="dialog-actions" style="justify-content:center"><button class="primary" id="more">Find another book</button><button class="secondary" id="again">Read it again</button></div></section>`;$('#more').onclick=home;$('#again').onclick=()=>{page=0;drawPage()}}
$('#search').oninput=render;$('#age').onchange=render;
document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{category=el.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b===el));render()});
$('#reset').onclick=()=>{$('#search').value='';$('#age').value='all';category='all';document.querySelector('[data-filter="all"]').click()};
$('#libraryNav').onclick=()=>{savedOnly=false;$('#libraryNav').classList.add('active');$('#savedNav').classList.remove('active');home()};
$('#savedNav').onclick=()=>{savedOnly=true;$('#savedNav').classList.add('active');$('#libraryNav').classList.remove('active');home()};
document.querySelectorAll('a.brand').forEach(a=>a.onclick=e=>{e.preventDefault();$('#libraryNav').click()});
$('.close').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close()};
$('#grownups').onclick=()=>{$('#detailBody').innerHTML='<span class="eyebrow">HELLO, GROWN-UPS</span><h2>A little room for wonder.</h2><p>Each page combines a short story with an activity. Children can explore freely, replay a favorite moment, or turn the page at any time.</p><p>Johnny Builds to Mars is an original demo story. The other books are new retellings of public-domain classics. The illustrations were created for this website.</p><p>Reading progress and saved books stay in this browser. Read-aloud uses your device’s available voices.</p>';$('#detail').showModal()};
document.addEventListener('keydown',e=>{if(!book||$('#detail').open||['INPUT','SELECT','BUTTON'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight')turn(page+1);if(e.key==='ArrowLeft')turn(page-1)});
